text:
#msgIdentity,
.address-container {
  min-block-size: 28px;
}

#msgSubject {
  min-block-size: 26px;
  margin-block-start: 0;
  padding-inline-start: 5px;
}

/* ::::: format toolbar ::::: */

#FormatToolbar {
  margin-block-end: 2px;
}

#FontFaceSelect {
  max-inline-size: 35ch;
}

toolbarbutton.formatting-button {
  margin: 1px;
}

/* ::::: address book sidebar ::::: */

#compose-toolbox {
  border-block-end: 1px solid var(--chrome-content-separator-color);
}

#compose-toolbox > toolbar:not([type="menubar"]) {
  padding: 2px 1px;

  :root[lwtheme] & {
    text-shadow: none;
  }
}
